import json

# Build grid with 4s at rows 19-21, cols 9 and 14-17
output_grid = []
for r in range(22):
    if r >= 19 and r <= 21:
        row = ['5']*26
        row[6] = '8'
        row[9] = '4'
        for c in range(14, 18):
            row[c] = '4'
    else:
        # Original box pattern
        if r in [0]:
            row = ['5'] + ['8']*7 + ['5'] + ['8']*16
        elif r in [1, 3, 4]:
            row = ['5'] + ['8']*3 + ['5']*5 + ['8'] + ['5']*11
        elif r in [15]:
            row = ['5'] + ['8']*10 + ['5']*15
        elif r in [16]:
            row = ['5'] + ['8']*3 + ['5']*5 + ['8'] + ['8'] + ['5']*16
        elif r in [17]:
            row = ['5'] + ['8']*3 + ['5']*5 + ['8'] + ['8']*16
        elif r in [18]:
            row = ['5'] + ['8']*7 + ['5']*18
        else:
            row = ['5']*26

    # Verify row length
    if len(row) != 26:
        row = ['5'] + row[:25]

    output_grid.append(row)

print(f"Grid size: {len(output_grid)}x{len(output_grid[0])}")
print(f"4s at rows 19-21, cols 9 and 14-17")

